fn enc_subject(out: &mut Vec<u8>, v: &Subject, depth: i32) {
    out.push(b'{');
    out.push(b'\n');
    pad(out, depth + 1);
    esc(out, "account");
    out.extend_from_slice(b": ");
    esc(out, &v.account);
    out.push(b',');
    out.push(b'\n');
    pad(out, depth + 1);
    esc(out, "program");
    out.extend_from_slice(b": ");
    esc(out, &v.program);
    out.push(b'\n');
    pad(out, depth);
    out.push(b'}');
}

