    let mut field_state: String = Default::default();
    let mut field_scope: Scope = Default::default();
    let mut field_registered_by: Subject = Default::default();
    let mut field_registered: String = Default::default();
    let mut field_expires: String = Default::default();
    let mut field_header: String = Default::default();
    let mut field_last_applied: String = Default::default();
    let mut seen: u32 = 0;
    r.skip_ws();
