fn decode_store_result(r: &mut Reader) -> Result<StoreResult, Refusal> {
    if r.at() != b'{' {
        return r.refuse("wrong_type");
    }
    r.enter()?;
    r.pos += 1;
    let mut field_outcome: Option<String> = None;
    let mut field_revision: String = Default::default();
    let mut field_current: Option<Metadata> = None;
    let mut seen: u32 = 0;
    r.skip_ws();
    if r.at() != b'}' {
        loop {
            r.skip_ws();
            if r.at() != b'"' {
                return r.refuse("malformed");
            }
            let key = r.string()?;
            r.skip_ws();
            if r.at() != b':' {
                return r.refuse("malformed");
            }
            r.pos += 1;
            r.skip_ws();
            match key.as_str() {
                "outcome" => {
                    if seen & 1 != 0 {
                        return r.refuse("duplicate_field");
                    }
                    seen |= 1;
                    field_outcome = Some(r.string()?);
                }
                "revision" => {
                    if seen & 2 != 0 {
                        return r.refuse("duplicate_field");
                    }
                    seen |= 2;
                    field_revision = r.string()?;
                }
                "current" => {
                    if seen & 4 != 0 {
                        return r.refuse("duplicate_field");
                    }
                    seen |= 4;
                    field_current = Some(decode_metadata(r)?);
                }
                _ => {
                    return r.refuse("unknown_field");
                }
            }
            r.skip_ws();
            if r.at() != b',' {
                break;
            }
            r.pos += 1;
        }
    }
    if r.at() != b'}' {
        return r.refuse("malformed");
    }
    r.pos += 1;
    r.depth -= 1;
    if seen & 3 != 3 {
        return r.refuse("missing_field");
    }
    let Some(field_outcome) = field_outcome.as_deref().and_then(StoreOutcome::from_wire) else {
        return r.refuse("bad_enum");
    };
    Ok(StoreResult {
        outcome: field_outcome,
        revision: field_revision,
        current: field_current,
    })
}

